export default function BankrollTab() {
  const [baseBet, setBaseBet] = useState(200);
  const [turns, setTurns] = useState(5);
  const [strategy, setStrategy] = useState('martingale');
  const [targetProfit, setTargetProfit] = useState(10000);
  const [betType, setBetType] = useState('ambo_cabeza');
  const [simData, setSimData] = useState(() => simulateClientBankroll(200, 5, 'martingale', 10000, 'ambo_cabeza'));
  const [loading, setLoading] = useState(false);

  const fetchSimulation = async () => {
    setLoading(true);
    try {
      const res = await axios.get(
        `/api/bankroll/simulate?base_bet=${baseBet}&turns=${turns}&strategy=${strategy}&target_profit=${targetProfit}&bet_type=${betType}`
      );
      setSimData(res.data);
    } catch (err) {
      setSimData(simulateClientBankroll(baseBet, turns, strategy, targetProfit, betType));
    } finally {
      setLoading(false);
    }
  };"

