import { verifyClientTicket } from '../services/clientEngine';

export default function TicketWalletTab() {
  const [date, setDate] = useState('2026-08-18');
  const [lottery, setLottery] = useState('ciudad');
  const [shift, setShift] = useState('nocturna');

  const [ticketItems, setTicketItems] = useState([
    { id: 1, number: '28', amount: 500, position: 'cabeza' },
    { id: 2, number: '64', amount: 300, position: '10' },
    { id: 3, number: '728', amount: 200, position: 'cabeza' }
  ]);

  const [newNumber, setNewNumber] = useState('');
  const [newAmount, setNewAmount] = useState(200);
  const [newPos, setNewPos] = useState('cabeza');

  const [verificationResult, setVerificationResult] = useState(null);
  const [verifying, setVerifying] = useState(false);

  const handleAddItem = (e) => {
    e.preventDefault();
    if (!newNumber.trim()) return;
    setTicketItems([
      ...ticketItems,
      {
        id: Date.now(),
        number: newNumber.trim(),
        amount: Number(newAmount),
        position: newPos
      }
    ]);
    setNewNumber('');
  };

  const handleRemoveItem = (id) => {
    setTicketItems(ticketItems.filter(item => item.id !== id));
  };

