import fs from 'fs';
import path from 'path';

const componentsDir = 'src/components';
const files = fs.readdirSync(componentsDir).filter(f => f.endsWith('.jsx'));

let errors = 0;
files.forEach(file => {
  const content = fs.readFileSync(path.join(componentsDir, file), 'utf8');

  // Find JSX tags matching Lucide icon names or undefined variables
  const iconImportsMatch = content.match(/import \{([^}]+)\} from 'lucide-react'/);
  const importedIcons = iconImportsMatch ? iconImportsMatch[1].split(',').map(s => s.trim()) : [];

  // Check common icons used in JSX: <IconName ...
  const jsxTags = [...content.matchAll(/<([A-Z][a-zA-Z0-9]+)/g)].map(m => m[1]);

  const knownReactTags = ['React', 'ErrorBoundary', 'VipGate', 'PredictionsTab', 'HeatmapTab', 'DelaysTab', 'PatternsTab', 'MarkovTab', 'CrossTab', 'GeneratorTab', 'BankrollTab', 'RedoblonasProTab', 'DreamsTab', 'SympatheticTab', 'TicketWalletTab', 'LiveRadar', 'UpgradeModal', 'PromoPopupModal', 'AuthModal', 'AdminPanelModal'];

  jsxTags.forEach(tag => {
    if (!knownReactTags.includes(tag) && !importedIcons.includes(tag) && !content.includes(`const ${tag}`) && !content.includes(`function ${tag}`)) {
      console.error(`ERROR in ${file}: <${tag}> used in JSX but not imported or declared!`);
      errors++;
    }
  });
});

if (errors === 0) {
  console.log("ALL COMPONENTS PASSED ICON AND COMPONENT IMPORT AUDIT!");
} else {
  console.error(`Found ${errors} errors!`);
}
