  const [currentTime, setCurrentTime] = useState(() => new Date().toLocaleTimeString());
  const [selectedHitModal, setSelectedHitModal] = useState(null);

  const [data, setData] = useState(() => getClientDraws('all', 'all', 20, getLocalDateString()));"

