"python -c "
import requests, re, json, sqlite3, os
from bs4 import BeautifulSoup
from datetime import datetime

HEADERS = {'User-Agent': 'Mozilla/5.0'}

def detect_shift(text):
    t = text.lower()
    if 'previa' in t: return 'previa'
    if 'primera' in t: return 'primera'
    if 'matutina' in t: return 'matutina'
    if 'vespertina' in t: return 'vespertina'
    if 'nocturna' in t: return 'nocturna'
    return None

conn = sqlite3.connect('backend/quiniela.db')
cur = conn.cursor()

all_draws = {}
# Load existing
try:
    with open('../ingenieriajh-portal/public/api/draws.json', 'r', encoding='utf-8') as f:
        all_draws = json.load(f)
except Exception as e:
    pass

for base_url, lottery in [('https://www.lanacion.com.ar/loterias/quiniela-nacional/', 'ciudad'), ('https://www.lanacion.com.ar/loterias/quiniela-provincia/', 'provincia')]:
    try:
        r = requests.get(base_url, headers=HEADERS, timeout=10)
        if r.status_code == 200:
            soup = BeautifulSoup(r.text, 'html.parser')
            seen = set()
            for a in soup.find_all('a', href=True):
                href = a['href']
                if 'resultados' in href and href not in seen:
                    seen.add(href)
