667: export function simulateClientBankroll(baseBet = 200, turns = 5, strategy = "martingale", targetProfit = 10000, betType = "ambo_cabeza") {
668:   const bBet = Number(baseBet) || 200;
669:   const tTurns = Number(turns) || 5;
670:   const mult = betType === "ambo_cabeza" ? 70.0 : betType === "terno" ? 500.0 : betType === "ambo_5" ? 14.0 : betType === "ambo_10" ? 7.0 : 3.5;
