677:       if (t === 1) bet = bBet;
678:       else bet = Math.ceil((accumulated + bBet * mult * 0.15) / (mult - 1));
679:     } else if (strategy === "dalembert") {
680:       bet = bBet + (t - 1) * (bBet * 0.5);
