import requests, re
from bs4 import BeautifulSoup

h = {'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36'}

print('=== CONSULTANDO LOTBA OFICIAL (18:00 VESPERTINA) ===')
try:
    r_home = requests.get('https://quiniela.loteriadelaciudad.gob.ar/', headers=h, timeout=8)
    soup = BeautifulSoup(r_home.text, 'html.parser')
    sorteos = []
    for tr in soup.find_all('tr'):
        tds = [td.get_text(strip=True) for td in tr.find_all('td')]
        if len(tds) >= 3 and re.match(r'^\d{5}$', tds[0]):
            sorteos.append((tds[0], tds[1], tds[2]))
    print('Sorteos en LOTBA:', sorteos[:6])

    for s_id, s_shift, s_time in sorteos[:6]:
        for jur, lot in [('51', 'Ciudad'), ('53', 'Provincia')]:
            r_post = requests.post('https://quiniela.loteriadelaciudad.gob.ar/resultadosQuiniela/consultaResultados.php', 
                                   data={'codigo': '0080', 'juridiccion': jur, 'sorteo': s_id}, 
                                   headers=h, timeout=8)
            ps = {}
            for td in BeautifulSoup(r_post.text, 'html.parser').find_all('td'):
                pos_div = td.find('div', class_='pos')
                if pos_div:
                    p_num = pos_div.get_text(strip=True)
                    v_divs = td.find_all('div')
                    if len(v_divs) >= 2:
                        ps[p_num] = v_divs[1].get_text(strip=True)
            if len(ps) == 20:
                print(f'  [LOTBA] {s_shift} ({s_time}) {lot}: 1°={ps.get(\"01\")} (20 numeros OK)')
except Exception as e:
    print('Error LOTBA:', e)
""

