      const docId = `user_${cleanEmail.replace(/[^a-zA-Z0-9]/g, '_')}`;

      const userData = {
        id: docId,
        name: displayName,
        email: cleanEmail,
        photoURL: `https://api.dicebear.com/7.x/bottts/svg?seed=${cleanEmail}`,
        is_vip: 1,
        vip_days_left: isAdmin ? 365 : 15,
