"const fs = require('fs');
const path = require('path');

const files = [
  'frontend/src/components/DrawsHistoryTab.jsx',
  'frontend/src/components/StatsRadarTab.jsx',
  'frontend/src/components/BankrollTab.jsx',
  'frontend/src/components/PredictionsTab.jsx',
  'frontend/src/components/DreamsTab.jsx',
  'frontend/src/components/TicketWalletTab.jsx',
  'frontend/src/App.jsx'
];

files.forEach(file => {
  const fullPath = path.resolve(file);
  if (!fs.existsSync(fullPath)) return;
  const content = fs.readFileSync(fullPath, 'utf8');

  // Lucide imports
  const lucideMatch = content.match(/from\s+['"]lucide-react['"]/);
  let lucideImports = [];
  if (lucideMatch) {
    const importBlock = content.match(/import\s*\{([\s\S]*?)\}\s*from\s*['"]lucide-react['"]/);
    if (importBlock) {
      lucideImports = importBlock[1].split(',').map(s => s.trim()).filter(Boolean);
    }
  }

  // Component imports
  const defaultImports = [...content.matchAll(/import\s+([A-Z][a-zA-Z0-9]+)\s+from/g)].map(m => m[1]);
  const namedImportsMatch = [...content.matchAll(/import\s*\{([\s\S]*?)\}\s*from\s*['"](?!\b(lucide-react)\b)[^'"]+['"]/g)];
  let namedImports = [];
  namedImportsMatch.forEach(m => {
    namedImports = namedImports.concat(m[1].split(',').map(s => s.trim()).filter(Boolean));
  });

  const localDefs = [...content.matchAll(/(?:function|class|const|let|var)\s+([A-Z][a-zA-Z0-9]+)/g)].map(m => m[1]);

  const allAvailable = new Set([...lucideImports, ...defaultImports, ...namedImports, ...localDefs, 'React', 'Fragment']);

  const tags = [...content.matchAll(/<([A-Z][a-zA-Z0-9]+)/g)].map(m => m[1]);
  const missing = [...new Set(tags)].filter(t => !allAvailable.has(t));
  console.log(file + ' => ' + (missing.length ? 'MISSING: ' + missing.join(', ') : 'OK'));
});
"

