const fs = require('fs');
const path = require('path');

function checkDir(dir) {
  const files = fs.readdirSync(dir);
  for (const f of files) {
    const full = path.join(dir, f);
    if (fs.statSync(full).isDirectory()) {
      checkDir(full);
    } else if (f.endsWith('.jsx') || f.endsWith('.js')) {
      const content = fs.readFileSync(full, 'utf8');
      const lucideMatch = content.match(/import\s*\{([^}]+)\}\s*from\s*'lucide-react'/);
      if (lucideMatch) {
        const imported = new Set(lucideMatch[1].split(',').map(s => {
          const parts = s.trim().split(/\s+as\s+/);
          return parts.length > 1 ? parts[1].trim() : parts[0].trim();
        }));
        const iconMatches = [...content.matchAll(/<([A-Z][A-Za-z0-9]+)/g)].map(m => m[1]);
        // list of known non-lucide components
        const localComps = ['App', 'PredictionsTab', 'DrawsHistoryTab', 'BankrollTab', 'DreamsTab', 'StatsRadarTab', 'TicketWalletTab', 'LiveRadar', 'VipGate', 'UpgradeModal', 'PromoPopupModal', 'AuthModal', 'AdminPanelModal', 'GuideModal', 'SettingsModal', 'WelcomeAuthScreen', 'ContactSupportModal', 'FeedbackModal', 'UserProfileModal', 'AiAdvisorFloatingModal', 'NotificationsModal', 'BroadcastPopupModal', 'ErrorBoundary', 'Fragment'];
        const missing = iconMatches.filter(tag => !imported.has(tag) && !localComps.includes(tag));
        if (missing.length > 0) {
          console.log('FILE WITH MISSING:', full, missing);
        }
      }
    }
