// Sort chronologically
draws.sort((a, b) => (a.draw_date + a.shift).localeCompare(b.draw_date + b.shift));

const N = draws.length;
console.log('Total valid draws:', N);

// Head counts & delays
const stats = {};
for (let i = 0; i < 100; i++) {
  const num = i.toString().padStart(2, '0');
  stats[num] = { num, headCount: 0, boardCount: 0, lastHeadIdx: -1, lastBoardIdx: -1 };
}

draws.forEach((d, idx) => {
  if (stats[d.head_ambo]) {
    stats[d.head_ambo].headCount++;
    stats[d.head_ambo].lastHeadIdx = idx;
  }
  d.board.forEach(item => {
    const ambo = item.slice(-2);
    if (stats[ambo]) {
      stats[ambo].boardCount++;
      stats[ambo].lastBoardIdx = idx;
    }
  });
});

for (let i = 0; i < 100; i++) {
  const num = i.toString().padStart(2, '0');
  stats[num].headDelay = stats[num].lastHeadIdx >= 0 ? N - 1 - stats[num].lastHeadIdx : N;
  stats[num].boardDelay = stats[num].lastBoardIdx >= 0 ? N - 1 - stats[num].lastBoardIdx : N;

  // Normalized score 0-100
  const freqScore = Math.min(40, (stats[num].headCount / 35) * 40);
  const delayScore = Math.min(30, (stats[num].headDelay / 100) * 30);
  const boardScore = Math.min(30, (stats[num].boardCount / 500) * 30);
  stats[num].compositeScore = Number((10 + freqScore * 0.45 + delayScore * 0.35 + boardScore * 0.20).toFixed(1));
}

const ranked = Object.values(stats).sort((a, b) => b.compositeScore - a.compositeScore).slice(0, 5);
console.log('Top 5 mathematically ranked ambos:');
ranked.forEach(r => {
  console.log('  Ambo:', r.num, 'Score:', r.compositeScore, 'HeadHits:', r.headCount, 'HeadDelay:', r.headDelay, 'BoardHits:', r.boardCount);
});
