"import json
import subprocess

script = """
import { ensureAllUpcomingCanonicalRecords, getOrLockUpcomingCanonicalPrediction } from './frontend/src/services/preDrawService.js';
import { getCanonicalLedger } from './frontend/src/services/canonicalPredictionsLedger.js';

const dateStr = '2026-09-05';
const shift = 'previa';

const records = ensureAllUpcomingCanonicalRecords(dateStr, shift);

// Simulating UI resolution logic exactly as in PredictionsTab.jsx:
function getUITop5(jurisdiction, engineId) {
  const rec = getOrLockUpcomingCanonicalPrediction(dateStr, jurisdiction, shift, engineId);
  return rec.top_5;
}

const tests = [
  { engine: 'ML-FULL', jurisdiction: 'ciudad', rec: records.ciudad_ml },
  { engine: 'STATISTICAL', jurisdiction: 'ciudad', rec: records.ciudad_stat },
  { engine: 'ML-FULL', jurisdiction: 'provincia', rec: records.provincia_ml },
  { engine: 'STATISTICAL', jurisdiction: 'provincia', rec: records.provincia_stat }
];

const results = [];

for (const t of tests) {
  const uiTop5 = getUITop5(t.jurisdiction, t.engine);
  const canonicalTop5 = t.rec.top_5;
  const match = JSON.stringify(uiTop5) === JSON.stringify(canonicalTop5);
  results.push({
    engine: t.engine,
    jurisdiction: t.jurisdiction,
    shift: t.rec.shift,
    draw_time: t.rec.draw_time,
    prediction_id: t.rec.prediction_id,
    top_5: canonicalTop5,
    created_at: t.rec.created_at,
    locked_at: t.rec.locked_at,
    deadline: t.rec.deadline,
    status: t.rec.status,
    prediction_hash: t.rec.prediction_hash,
    ui_top5: uiTop5,
    canonical_top5: canonicalTop5,
    ui_canonical_match: match ? 'PASS' : 'FAIL'
  });
}

console.log(JSON.stringify(results, null, 2));
"""

