const res = {};

for (const jur of ['ciudad', 'provincia']) {
  const mlRes = getMLPredictions(jur, shift, 100, dateStr);
  res[`${jur}_ml_ranking`] = mlRes.top_predictions.map(p => p.number);
  const mlScores = {};
  mlRes.top_predictions.forEach(p => {
    mlScores[p.number] = p.composite_score || 80;
