  const statList = statRes.top_predictions || statRes.predictions || [];
  res[`${jur}_stat_ranking`] = statList.map(p => p.number);
  const statScores = {};
  statList.forEach(p => {
    statScores[p.number] = p.composite_score || p.predictive_score || 75;
  });
  res[`${jur}_stat_scores`] = statScores;
}

fs.writeFileSync(
