"// 1. Check Canonical Ledger visible records
console.log('--- CANONICAL LEDGER ACTIVE RECORDS ---');
checks.forEach(({ jur, engine, expected_draw, target_id }) => {
  const canonical = getCanonicalPrediction('2026-09-05', jur, 'vespertina', engine);
  if (!canonical) {
    console.error(`FAIL: Canonical record missing for ${jur} ${engine}`);
    allPass = false;
    return;
  }
  let uiTop5 = [];
  if (engine === 'ML-FULL') {
    uiTop5 = getMLPredictions(jur, 'vespertina', 5, '2026-09-05').top_predictions.map(p => p.number);
  } else {
    const statRes = getClientPredictions(jur, 'vespertina', 5);
    uiTop5 = (statRes.top_predictions || statRes.predictions || []).slice(0, 5).map(p => p.number);
  }
  const match = uiTop5.join(',') === canonical.top_5.join(',');
  const drawMatch = String(canonical.expected_draw_number) === expected_draw;
  const statusMatch = canonical.status === 'LOCKED';
  const idMatch = canonical.prediction_id === target_id;

  console.log(`[${match && drawMatch && statusMatch && idMatch ? 'PASS' : 'FAIL'}] ${canonical.prediction_id}:`);
  console.log(`   Canonical Top 5:     ${canonical.top_5.join(',')}`);
  console.log(`   UI Top 5:            ${uiTop5.join(',')}`);
  console.log(`   UI_CANONICAL_MATCH:  ${match ? 'PASS' : 'FAIL'}`);
  console.log(`   expected_draw_number: ${canonical.expected_draw_number} (Matches Official 52870: ${drawMatch})`);
  console.log(`   Hash:                ${canonical.prediction_hash}`);
  console.log(`   Status:              ${canonical.status}`);
  console.log(`   Locked at:           ${canonical.locked_at}`);
  console.log(`   Deadline:            ${canonical.deadline}\n`);

  if (!match || !drawMatch || !statusMatch || !idMatch) allPass = false;
});"

